import sys

def main():
    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n = int(sys.stdin.readline())
    xs = []
    ys = []
    for _ in range(n):
        x, y = readints()
        xs.append(x)
        ys.append(y)
    d = int(sys.stdin.readline())

    xs.sort()
    ys.sort()

    def is_feasible(x_star, y_star):
        return all(abs(x - x_star) + abs(y - y_star) <= d for x, y in zip(xs, ys))

    def total_distance(x_star, y_star):
        return sum(abs(x - x_star) for x in xs) + sum(abs(y - y_star) for y in ys)

    def find_optimal_intersection():
        min_total_distance = float('inf')
        best_x_star = None
        best_y_star = None

        # Binary search for x_star
        left_x = xs[0]
        right_x = xs[-1]
        while left_x <= right_x:
            mid_x = (left_x + right_x) // 2
            if is_feasible(mid_x, ys[len(ys) // 2]):
                right_x = mid_x - 1
            else:
                left_x = mid_x + 1

        # Binary search for y_star
        left_y = ys[0]
        right_y = ys[-1]
        while left_y <= right_y:
            mid_y = (left_y + right_y) // 2
            if is_feasible(xs[len(xs) // 2], mid_y):
                right_y = mid_y - 1
            else:
                left_y = mid_y + 1

        # Check the closest feasible points
        for x_star in [left_x, right_x]:
            for y_star in [left_y, right_y]:
                if is_feasible(x_star, y_star):
                    dist = total_distance(x_star, y_star)
                    if dist < min_total_distance:
                        min_total_distance = dist
                        best_x_star = x_star
                        best_y_star = y_star

        return min_total_distance if best_x_star is not None else "impossible"

    result = find_optimal_intersection()
    print(result)

